import solara

import mesa
from mesa.visualization.solara_viz import ModelController, ModelCreator


class PlainModel(mesa.Model):
    def __init__(self, num_agents=10, **kwargs):
        super().__init__()
        self.num_agents = num_agents


reactive_model = solara.reactive(PlainModel(num_agents=2))


@solara.component
def TestDefaults():
    ModelController(reactive_model)
    ModelCreator(
        reactive_model,
        {"num_agents": {"type": "SliderInt", "value": 2, "min": 1, "max": 5}},
    )


try:
    solara.render(TestDefaults(), handle_error=False)
    print("PASS: standalone render with default (None) model_parameters")
except Exception as e:
    print("FAIL:", type(e).__name__, e)
","file_path":"/testbed/verify_standalone.py"}

